6	
7	type Row={id:string;version:number;description:string;posted_on:string;amount_minor:string;currency_code:string};
8	type Target={id:string;name:string};
9	type Item={row:Row;proposal:OrganizationProposal};
10	const field='min-h-10 rounded-lg border border-border bg-card px-3 py-2 text-sm text-foreground';
11	// Typed name -> [existing id | 'new' | 'keep', new name].
12	function choice(targets:Target[],name:string):[string,string]{
13	 const trimmed=name.trim();if(!trimmed)return ['keep',''];
14	 const found=targets.find(target=>target.name.toLowerCase()===trimmed.toLowerCase());
15	 return found?[found.id,'']:['new',trimmed];
16	}
17	/** Same-description entries together, newest first in each group, so one press can select a run of them. */
18	export function groupedByDescription<T extends { row: { description: string; posted_on: string } }>(items: T[]) {
19	  const groups = new Map<string, T[]>();
20	  for (const item of items) { const key = item.row.description.trim().toLocaleLowerCase("en"); groups.set(key, [...(groups.get(key) ?? []), item]); }
21	  return [...groups.values()].map(group => [...group].sort((a, b) => b.row.posted_on.localeCompare(a.row.posted_on)));
22	}
23	
24	export function OrganizationQueue({items,merchants,categories,requestId,locale}:{items:Item[];merchants:Target[];categories:Target[];requestId:string;locale:string}) {
