content.content:
1	'use client';
2	import { Fragment,useActionState,useEffect,useRef,useState} from 'react';
3	import {createReview,applyReview,undoReview} from './actions';
4	import {formatMoney} from '@/lib/finance/format';
5	import type {OrganizationProposal} from '@/lib/import/organization';
6	
7	type Row={id:string;version:number;description:string;posted_on:string;amount_minor:string;currency_code:string};
8	type Target={id:string;name:string};
9	type Item={row:Row;proposal:OrganizationProposal};
10	const field='min-h-10 rounded-lg border border-border bg-card px-3 py-2 text-sm text-foreground';
11	// Typed name -> [existing id | 'new' | 'keep', new name].
12	function choice(targets:Target[],name:string):[string,string]{
13	 const trimmed=name.trim();if(!trimmed)return ['keep',''];
14	 const found=targets.find(target=>target.name.toLowerCase()===trimmed.toLowerCase());
15	 return found?[found.id,'']:['new',trimmed];
16	}
17	/** Same-description entries together, newest first in each group, so one press can select a run of them. */
18	export function groupedByDescription<T extends { row: { description: string; posted_on: string } }>(items: T[]) {
19	  const groups = new Map<string, T[]>();
20	  for (const item of items) { const key = item.row.description.trim().toLocaleLowerCase("en"); groups.set(key, [...(groups.get(key) ?? []), item]); }
21	  return [...groups.values()].map(group => [...group].sort((a, b) => b.row.posted_on.localeCompare(a.row.posted_on)));
22	}
23	
24	export function OrganizationQueue({items,merchants,categories,requestId,locale}:{items:Item[];merchants:Target[];categories:Target[];requestId:string;locale:string}) {
25	 const [state,action,pending]=useActionState(createReview,{});
26	 const [selected,setSelected]=useState<string[]>([]);
27	 const [merchant,setMerchant]=useState('');
28	 const [category,setCategory]=useState('');
29	 const [assistance,setAssistance]=useState('');
30	 const [providerBusy,setProviderBusy]=useState(false);
31	 const draftRevision=useRef(0);
32	 const nameOf=(targets:Target[],id:string|null)=>id?targets.find(target=>target.id===id)?.name??'':'';
33	 const suggestion=(proposal:Pick<OrganizationProposal,'merchantId'|'merchantName'|'categoryId'>)=>[proposal.merchantName??nameOf(merchants,proposal.merchantId),nameOf(categories,proposal.categoryId)];
34	 const fill=(proposal:Pick<OrganizationProposal,'merchantId'|'merchantName'|'categoryId'>)=>{const [m,c]=suggestion(proposal);setMerchant(m);setCategory(c);};
35	 const rows=items.filter(item=>selected.includes(item.row.id)).map(({row:{id,version}})=>({id,version}));
36	 const [merchantValue,merchantName]=choice(merchants,merchant);
37	 const [categoryValue,categoryName]=choice(categories,category);
38	 const toggle=(ids:string[],on:boolean)=>{draftRevision.current++;setSelected(on?[...new Set([...selected,...ids])]:selected.filter(id=>!ids.includes(id)));};
39	 function applySuggestion(proposal:OrganizationProposal){
40	  const key=JSON.stringify(suggestion(proposal));draftRevision.current++;
41	  setSelected([...new Set([...selected,...items.filter(item=>JSON.stringify(suggestion(item.proposal))===key).map(item=>item.row.id)])]);fill(proposal);
42	 }
43	 async function requestSuggestions(){
44	  const requestedRevision=draftRevision.current;
45	  setProviderBusy(true);setAssistance('');
46	  try{
47	   const response=await fetch('/api/money/organization/suggestions',{method:'POST',headers:{'Content-Type':'application/json'},signal:AbortSignal.timeout(25000),body:JSON.stringify({rows,useProvider:true})});
48	   const body=await response.json() as {proposals?:OrganizationProposal[];providerStatus?:string;notice?:string};
49	   if(draftRevision.current!==requestedRevision){setAssistance('Your draft changed while suggestions were requested. Keep your choices or ask again.');return;}
50	   if(!response.ok||body.providerStatus!=='available'){setAssistance(body.notice??'AI suggestions are unavailable right now.');return;}
51	   const candidates=(body.proposals??[]).filter(candidate=>selected.includes(candidate.transactionId)&&candidate.basis==='provider-suggestion');
52	   const choices=new Set(candidates.map(candidate=>JSON.stringify([candidate.merchantId,candidate.merchantName,candidate.categoryId])));
53	   if(candidates.length&&candidates.length===selected.length&&choices.size===1){fill(candidates[0]);setAssistance('Filled from an AI suggestion. Check it in the preview before approving.');}
54	   else setAssistance(candidates.length?'AI suggestions differ across the selection. Select fewer entries.':'No AI suggestions were returned.');
55	  }catch{setAssistance('AI suggestions are unavailable right now.');}
56	  finally{setProviderBusy(false);}
57	 }
58	 const chosen=items.filter(item=>selected.includes(item.row.id));
59	 const keys=new Set(chosen.map(item=>item.proposal.descriptionKey));
60	 const ruleKey=keys.size===1&&[...keys][0].length>=3?[...keys][0]:null;
61	 const unchecked=chosen.filter(item=>item.proposal.financialReviewRequired).length;
62	 const similarCount=(proposal:OrganizationProposal)=>{const key=JSON.stringify(suggestion(proposal));return items.filter(item=>JSON.stringify(suggestion(item.proposal))===key).length;};
63	 const selectAll=useRef<HTMLInputElement>(null);
64	 useEffect(()=>{if(selectAll.current)selectAll.current.indeterminate=selected.length>0&&selected.length<items.length;},[selected.length,items.length]);
65	 const noTarget=merchantValue==='keep'&&categoryValue==='keep';
66	 const created=[categoryName&&`category “${categoryName}”`,merchantName&&`merchant “${merchantName}”`].filter(Boolean).join(' and ');
67	 return <form action={action} className="rounded-xl border border-border bg-card">
68	  <input type="hidden" name="rows" value={JSON.stringify(rows)} />
69	  <input type="hidden" name="requestId" value={requestId} />
70	  <input type="hidden" name="merchant" value={merchantValue} /><input type="hidden" name="merchantName" value={merchantName} />
71	  <input type="hidden" name="category" value={categoryValue} /><input type="hidden" name="categoryName" value={categoryName} />
72	  <div id="organize-controls" className="flex scroll-mt-24 flex-wrap items-end gap-3 border-b border-border p-4">
73	   <label className="flex min-h-10 items-center gap-2 text-sm"><input ref={selectAll} type="checkbox" checked={items.length>0&&selected.length===items.length} onChange={event=>toggle(items.map(item=>item.row.id),event.target.checked)} />{selected.length?`${selected.length} selected`:'Select all'}</label>
74	   <label className="grid gap-1 text-xs text-muted-foreground">Category<input name="categorySearch" list="organize-categories" value={category} onChange={event=>{draftRevision.current++;setCategory(event.target.value);}} maxLength={100} placeholder="Keep current, or type a name" className={field} /></label>
75	   <label className="grid gap-1 text-xs text-muted-foreground">Merchant<input name="merchantSearch" list="organize-merchants" value={merchant} onChange={event=>{draftRevision.current++;setMerchant(event.target.value);}} maxLength={100} placeholder="Keep current, or type a name" className={field} /></label>
76	   <datalist id="organize-categories">{categories.map(target=><option key={target.id} value={target.name} />)}</datalist>
77	   <datalist id="organize-merchants">{merchants.map(target=><option key={target.id} value={target.name} />)}</datalist>
78	   <button disabled={pending||providerBusy||!rows.length||noTarget} className="min-h-10 rounded-lg bg-brand px-4 py-2 text-sm font-medium text-white disabled:opacity-40">{pending?'Applying…':rows.length?`Apply to ${rows.length}`:'Apply'}</button>
79	   <label className={'flex min-h-10 items-center gap-2 text-sm'+(ruleKey?'':' text-muted-foreground')}><input type="checkbox" name="saveRule" value="true" disabled={!ruleKey} />{ruleKey?'Suggest the same for future entries like “'+ruleKey+'”':'Suggest the same for future entries (needs one description selected)'}</label>
80	   <button type="button" disabled={providerBusy||pending||!rows.length} onClick={requestSuggestions} className="min-h-10 text-sm text-muted-foreground underline disabled:opacity-40">{providerBusy?'Asking AI…':'Suggest with AI'}</button>
81	   {created&&<p className="basis-full text-xs text-muted-foreground">New {created} will be created. Capital letters don’t matter when matching an existing name.</p>}
82	   {unchecked>0&&<p className="basis-full text-xs text-warning">{unchecked} selected still {unchecked===1?'needs its':'need their'} amount checked. A category doesn’t confirm the amount.</p>}
83	   {assistance&&<p role="status" className="basis-full text-sm">{assistance}</p>}
84	   {state.error&&<p role="alert" className="basis-full text-sm text-danger">{state.error}{state.reviewId&&<> <a className="underline" href={'/money/organization?review='+state.reviewId}>Open the saved review</a></>}</p>}
