7	 useActionState:()=>[{},vi.fn(),false],useRef:(value:unknown)=>({current:value}),useEffect:()=>{},
8	 useState:(value:unknown)=>{const index=state.length;state.push(value);return [value,(next:unknown)=>{state[index]=next;}];},
9	}));
10	const id='00000000-0000-4000-8000-000000000001';
11	function element(node:ReactNode,type:string,name?:string,prop='name'):Record<string,unknown>|undefined{
12	 if(!isValidElement<{children?:ReactNode;[key:string]:unknown}>(node))return;
13	 if(node.type===type&&(!name||node.props[prop]===name))return node.props;
14	 for(const child of Children.toArray(node.props.children)){const found=element(child,type,name,prop);if(found)return found;}
