import { createRequire } from "node:module";
const require = createRequire(`${process.cwd()}/`);
process.loadEnvFile(".env");
const { default: postgres } = await import(require.resolve("postgres").replace(/\\/g, "/").replace(/^([A-Z]):/, "file:///$1:"));
const db = postgres(process.env.SUPABASE_DB_URL, { ssl: "require", max: 1 });
const [row] = await db`select statements, array_length(statements,1) n from supabase_migrations.schema_migrations where version='202611040004'`;
const norm = s => s.replaceAll("\r\n", "\n").trim();
const applied = norm(row.statements.join("\n"));
const file = norm(readFileSync("supabase/migrations/202611040004_import_row_decision_undo.sql", "utf8"));
console.log({ statements: row.n, appliedLength: applied.length, fileLength: file.length, equal: applied === file });
let i = 0; while (i < applied.length && applied[i] === file[i]) i++;
if (applied !== file) console.log({ at: i, applied: JSON.stringify(applied.slice(Math.max(0, i - 80), i + 80)), file: JSON.stringify(file.slice(Math.max(0, i - 80), i + 80)) });
await db.end();

